def solve_langford():
    # pairs for each v
    pairs = {}
    for v in range(1, 9):
        d = v + 1
        lst = []
        for i in range(1, 17 - d):
            lst.append((i, i+d))
        pairs[v] = lst

    # fixed values
    fixed = {4:7, 8:5, 10:4}

    used = [False]*17
    seq = [0]*17

    # Pre-mark fixed for 7: (4,12)
    used[4] = used[12] = True
    seq[4] = seq[12] = 7

    def get_candidates(v):
        if v in fixed:
            pos = fixed[v]
            d = v + 1
            cand = []
            if pos - d >= 1:
                cand.append((pos-d, pos))
            if pos + d <= 16:
                cand.append((pos, pos+d))
            return cand
        else:
            return pairs[v]

    order = [8,7,6,5,4,3,2,1]

    def backtrack(idx):
        if idx == len(order):
            return True
        v = order[idx]
        if v == 7:
            return backtrack(idx+1)
        for p in get_candidates(v):
            i, j = p
            if not used[i] and not used[j]:
                used[i] = used[j] = True
                seq[i] = seq[j] = v
                if backtrack(idx+1):
                    return True
                used[i] = used[j] = False
                seq[i] = seq[j] = 0
        return False

    if backtrack(0):
        return seq[1:]  # 0-indexed list
    else:
        return None

