def solve_langford_general(n, fixed={}):
    # pairs for each v
    pairs = {}
    for v in range(1, n+1):
        d = v + 1
        lst = []
        for i in range(1, 2*n - d + 1):
            lst.append((i, i+d))
        pairs[v] = lst

    used = [False]*(2*n+1)
    seq = [0]*(2*n+1)

    # Apply fixed that are already determined (like if a position is fixed, we might not know the pair yet)
    # But for now, assume fixed dict maps position->value, and we haven't resolved pairs.
    # We'll just use get_candidates that respects fixed.

    def get_candidates(v):
        if v in fixed:
            pos = fixed[v]
            d = v + 1
            cand = []
            if pos - d >= 1:
                cand.append((pos-d, pos))
            if pos + d <= 2*n:
                cand.append((pos, pos+d))
            return cand
        else:
            return pairs[v]

    # Order: larger v first
    order = list(range(n, 0, -1))

    # But we might have some v with fixed positions that are already forced.
    # For any v where fixed position is given, we could immediately place if only one candidate, but we'll just search.

    def backtrack(idx):
        if idx == len(order):
            return True
        v = order[idx]
        # If v already placed due to forced pair? Not implemented.
        for p in get_candidates(v):
            i, j = p
            if not used[i] and not used[j]:
                used[i] = used[j] = True
                seq[i] = seq[j] = v
                if backtrack(idx+1):
                    return True
                used[i] = used[j] = False
                seq[i] = seq[j] = 0
        return False

    if backtrack(0):
        return seq[1:]
    else:
        return None

