def solve_langford_8():
    n = 8
    pairs = {}
    for v in range(1, n+1):
        d = v + 1
        lst = []
        for i in range(1, 2*n - d + 1):
            lst.append((i, i+d))
        pairs[v] = lst

    # fixed: position -> value
    fixed_pos = {4:7, 8:5, 10:4}
    # invert: value -> position
    fixed_val = {v: p for p, v in fixed_pos.items()}

    used = [False]*(2*n+1)
    seq = [0]*(2*n+1)

    # For value 7, position 4 fixed => pair must be (4,12)
    # Let's pre-place forced pairs if only one option.
    # Actually we can just search.

    def get_candidates(v):
        if v in fixed_val:
            pos = fixed_val[v]
            d = v + 1
            cand = []
            if pos - d >= 1:
                cand.append((pos-d, pos))
            if pos + d <= 2*n:
                cand.append((pos, pos+d))
            return cand
        else:
            return pairs[v]

    order = list(range(n, 0, -1))

    def backtrack(idx):
        if idx == len(order):
            return True
        v = order[idx]
        for p in get_candidates(v):
            i, j = p
            if not used[i] and not used[j]:
                used[i] = used[j] = True
                seq[i] = seq[j] = v
                if backtrack(idx+1):
                    return True
                used[i] = used[j] = False
                seq[i] = seq[j] = 0
        return False

    if backtrack(0):
        return seq[1:]
    else:
        return None

