def verify(seq):
    n = max(seq)
    # Check each number appears exactly twice
    from collections import Counter
    cnt = Counter(seq)
    for v in range(1, n+1):
        if cnt[v] != 2:
            return False, f"count of {v} is {cnt[v]}"
    # Check distances
    pos = {}
    for i, val in enumerate(seq, start=1):
        pos.setdefault(val, []).append(i)
    for v in range(1, n+1):
        p1, p2 = pos[v]
        if p2 - p1 != v + 1:
            return False, f"distance for {v}: {p2-p1} != {v+1}"
    return True, "OK"

